S(G2,'support-ticket','Ticket detail','The thread with properties and linked issues beside it.',()=>K.shell('support','Tickets',{title:tickets[2].s,sub:tickets[2].id,actions:`${H.btn('Merge','ghost sm')}${H.btn('Resolve','primary sm','check')}`,body:K.cols('1fr 300px',[`<div class="vstack" style="gap:14px;min-height:0">${K.tl([['mail',tickets[2].p.name,'When I sign in with Okta it sends me back to the login page. Tried two browsers.','10:02'],['msg',pp[1].name+' replied','Thanks — can you share the time you tried and your workspace URL?','10:15'],['mail',tickets[2].p.name,'10:20 CET, helm.app/w/oakline','10:22'],['flag','Linked to ENG-482','SSO redirect loop for custom domains','10:30']])}<div style="margin-top:auto">${K.composer('Reply…')}</div></div>`,`<div class="vstack" style="gap:12px">${K.card('Properties',K.meta([['Status',K.sel('Open')],['Priority',K.tag('Urgent')],['Assignee',`${K.av(pp[1],'xs')} ${pp[1].first}`],['Team','Identity'],['SLA',`<span style="color:var(--warn)">2h 10m left</span>`],['Tags',H.tag('sso','line')+H.tag('okta','line')]]))}${K.card('Linked issue',`<div class="row" style="gap:10px">${I('branch',16)}<div class="grow"><b style="font-weight:500">ENG-482</b><div class="t-small">In progress · ships today</div></div>${H.spill('Fixing','info')}</div>`)}</div>`])}),'timeline,metadata-list,chat-composer');
