S(G2,'support-article','Article editor','Write help articles with a live outline.',()=>K.shell('support','Knowledge base',{title:'Export invoices to CSV',sub:'Billing & plans',actions:`${H.spill('Draft','')}${H.btn('Preview','ghost sm','eye')}${H.btn('Publish','primary sm')}`,body:K.cols('1fr 220px',[`<div class="rte" style="flex:1;display:flex;flex-direction:column"><div class="tb">${H.seg(['Text','H1','H2'],0,'sm')}${['bold','italic','under','list','link','image','code'].map(i=>H.ib(i,'ghost sm',i)).join('')}</div><div class="ed md" style="max-width:none;flex:1"><h4 style="font-size:22px;margin:0 0 10px">Export invoices to CSV</h4><p>You can export any range of invoices from <b>Billing → Invoices</b>. Exports include line items, tax and payment status.</p><h4>Before you start</h4><ul><li>You need the Owner or Billing role.</li><li>Exports above 5,000 rows are emailed to you.</li></ul><h4>Steps</h4><p>1. Open Billing → Invoices. 2. Pick a date range. 3. Choose <code class="code">Export → CSV</code>.</p></div></div>`,`<div class="vstack" style="gap:12px"><div class="t-label">On this page</div><nav class="outline"><a aria-current="true" href="#">Export invoices to CSV</a><a class="l2" href="#">Before you start</a><a class="l2" href="#">Steps</a></nav>${K.card('Settings',`<div class="vstack" style="gap:10px">${H.field('Collection',H.sel('Billing & plans'))}<div class="knob"><span>Show in widget</span>${H.sw(true,'sm')}</div></div>`)}</div>`])}),'rich-text-editor,outline,field');
S(G2,'support-macros','Macros','Saved replies and actions the team can run in one click.',()=>K.shell('support','Macros',{title:'Macros',actions:H.btn('New macro','primary sm','plus'),body:`${K.search('Search macros',300)}<div class="grid2">${[['Refund approved','Sets status to Resolved, adds tag refund',142],['Ask for screenshots','Replies with a screenshot guide',88],['Escalate to engineering','Assigns to Tier 2, links Jira',61],['SSO troubleshooting','Replies with the SSO checklist',57],['Billing email change','Replies, opens billing settings',33],['Close as duplicate','Merges and resolves',29]].map((m,i)=>`<div class="card pad row" style="gap:12px;align-items:flex-start"><span class="av sq" style="--t:var(--c${i%6+1})">${I('zap',14)}</span><div class="grow"><b>${m[0]}</b><div class="t-small">${m[1]}</div></div><span class="t-small num">${m[2]} uses</span></div>`).join('')}</div>`}),'card,input-group');
S(G2,'support-sla','SLA dashboard','Response and resolution times against targets.',()=>K.shell('support','SLAs',{title:'SLAs',sub:'Last 30 days',actions:H.seg(['7D','30D','90D'],1,'sm'),body:`${K.kpis([{icon:'clock',label:'First response',value:'38m',d:-12,sub:'Target 1h'},{icon:'check-c',label:'Resolution',value:'6.2h',d:-8,sub:'Target 8h'},{icon:'target',label:'SLA met',value:'94%',d:3},{icon:'alert',label:'Breaches',value:'7',d:-30}])}
${K.cols('1.4fr 1fr',[K.card('First response time',`${ch.line({series:[{d:ch.series(30,50,14,-.5,9),c:'c1',area:true}],labels:Array.from({length:30},(_,i)=>i%5?'':`${i+1}`),h:200})}`),K.card('By team',ch.bullet([{l:'Tier 1',v:96,t:90,b:[60,80]},{l:'Tier 2',v:84,t:90,b:[60,80]},{l:'Billing',v:92,t:90,b:[60,80]},{l:'Identity',v:71,t:90,b:[60,80]}]))],12,'flex:1')}`}),'stat,line-chart,bullet-chart');
S(G2,'support-csat','CSAT report','How customers rate support, and why.',()=>K.shell('support','Reports',{title:'Customer satisfaction',actions:H.btn('Export','sm','download'),body:`${K.cols('1fr 1fr 1fr',[K.card('Score',`<div class="vstack" style="align-items:center">${ch.gauge({v:92,label:'4.6',sub:'out of 5',size:200})}</div>`),K.card('Ratings',ch.barlist([['5 stars',612,'star'],['4 stars',201,'star'],['3 stars',48,'star'],['2 stars',14,'star'],['1 star',9,'star']])),K.card('Mix',`<div class="vstack" style="align-items:center;gap:10px">${ch.donut({data:[{v:70,c:'c6'},{v:23,c:'c3'},{v:7,c:'c5'}],label:'884',sub:'responses',size:150})}${ch.legend([{c:'c6',l:'Happy'},{c:'c3',l:'Neutral'},{c:'c5',l:'Unhappy'}],false)}</div>`)])}
${K.card('Recent comments',K.table([{h:'Customer',r:p=>`<span class="row" style="gap:8px">${K.av(p,'xs')}${p.name}</span>`},{h:'Rating',r:(p,i)=>`<span style="color:var(--c4)">${'★'.repeat(5-(i%3))}</span><span style="color:var(--line-3)">${'★'.repeat(i%3)}</span>`},{h:'Comment',r:(p,i)=>['Fixed in minutes, thanks Maya!','Took a day but solved it.','Had to explain twice.','Great docs link.'][i]}],pp.slice(3,7),{style:'box-shadow:none;border-radius:0'}),'','flex:1')}`}),'gauge-chart,bar-list,donut-chart,table');

